from pathlib import Path
from html import escape
from format_lecon import paras
D=Path(__file__).resolve().parents[1]
def quote(n,starts):
 lines=(D/f'evidence/AIPS_{n}.txt').read_text().splitlines();out=[]
 for s in starts:
  hits=[x for x in lines if x.startswith(s)];assert len(hits)==1,(n,s,len(hits));out.append('<p>« '+escape(hits[0])+' »</p>')
 return '<blockquote>'+'\n'.join(out)+'</blockquote>'
def cetirizine(l):
 d=paras('La cétirizine bloque les récepteurs H1 de l’histamine. Cetirizin-Mepha 10 est un comprimé pelliculé sécable à 10 mg, autorisation 65119, notice de mai 2023. Parmi ses indications suisses figure l’urticaire chronique idiopathique ; l’angio-œdème aigu n’est pas une indication explicitement nommée. Son emploi dans ce dernier contexte doit être distingué de l’indication autorisée et apprécié par le prescripteur.', 'La stratégie HUG recommande les antihistaminiques H1 pour les manifestations mastocytaires non menaçantes. La cétirizine ne traite pas une obstruction laryngée ni un choc anaphylactique. Les doses ci-dessous sont celles de la notice suisse dans l’urticaire chronique idiopathique, et non un protocole de traitement de l’anaphylaxie.')
 lines=(D/'evidence/AIPS_65119.txt').read_text().splitlines()
 a=lines.index('Rhinite allergique pérenne, urticaire chronique idiopathique');b=lines.index('Instructions posologiques particulières',a)
 d+='<blockquote><p>« '+escape(' '.join(lines[a:b]))+' »</p></blockquote>'
 a=lines.index('Adaptation posologique lors de diminution de la fonction rénale');b=lines.index('Patients âgés',a)
 d+='<p>Tableau rénal original pour les comprimés à 10 mg :</p><blockquote><p>« '+escape(' '.join(lines[a:b]))+' »</p></blockquote>'
 d+=quote('65119',["Déterminer l'intervalle posologique individuellement", "Aucune adaptation posologique n'est nécessaire si le patient", "Hypersensibilité au principe actif, la cétirizine", "Insuffisance rénale terminale (débit", "L'utilisation du comprimé pelliculé n'est pas recommandée", "La prudence est de mise en cas d'emploi pendant la grossesse.", "La cétirizine ne devrait pas être utilisée durant l'allaitement", "Parce que la cétirizine peut entraîner une somnolence accrue"])
 d+=paras('Pour cette forme, la dose usuelle à partir de 6 ans est de 10 mg par jour, avec possibilité de fractionnement selon la notice. Le tableau rénal adulte passe à 5 mg par jour entre 30 et moins de 60 ml/min. Entre 15 et moins de 30 ml/min, il prévoit 5 mg tous les deux jours chez les patients non dialysés. L’insuffisance rénale terminale sous 15 ml/min est une contre-indication. Ne pas transposer automatiquement ces paliers à un enfant ; une prescription pédiatrique adaptée est nécessaire.', 'La notice emploie la notion de débit de filtration absolu puis demande une estimation de la clairance de la créatinine en ml/min. Une valeur indexée à 1,73 m² ne doit pas être substituée sans vérifier l’adaptation requise. Chez la personne âgée, vérifier la fonction rénale ; une atteinte hépatique isolée ne nécessite pas d’adaptation, mais une atteinte rénale associée en nécessite une.', 'La somnolence reste possible malgré la classification de deuxième génération. Prévenir le patient concernant conduite, alcool et autres dépresseurs du système nerveux central. Prudence en cas de rétention urinaire, épilepsie ou risque convulsif. Le ritonavir augmente l’exposition à la cétirizine ; une revue complète des interactions est indiquée.', 'La grossesse exige une appréciation prudente du bénéfice et du risque. La notice déconseille l’emploi pendant l’allaitement en raison du passage dans le lait et des effets possibles sur le nourrisson. Le choix d’une autre stratégie relève du prescripteur, sans interrompre à tort un traitement vital de l’anaphylaxie.', 'La majoration jusqu’à quatre fois la dose mentionnée par les HUG concerne une stratégie d’urticaire chronique et dépasse la dose usuelle de cette notice. Elle ne constitue ni une automédication ni la réponse à une tuméfaction qui progresse vers les voies aériennes. La durée et toute majoration relèvent d’une réévaluation clinique ; aucune dose élevée n’est prescrite ici.')
 return l.subwindow('cetirizine','Cétirizine : indication, reins et sécurité',d,(14,1,8))
def berinert(l):
 d=paras('Berinert IV apporte un inhibiteur de la C1 estérase issu du plasma humain. La spécialité suisse décrite, autorisation 51950, est un flacon de 500 unités internationales à reconstituer avec 10 ml d’eau pour injection, soit 50 unités internationales par ml. La notice de mars 2022 indique la thérapie des crises aiguës d’angio-œdème héréditaire et la prophylaxie avant intervention chirurgicale.', 'La dose est calculée en unités internationales par kilogramme, puis convertie en volume de la solution reconstituée. Cette présentation intraveineuse ne doit pas être confondue avec une présentation sous-cutanée destinée à une autre modalité de traitement.')
 d+=quote('51950',["20 unités internationales/par kg de poids corporel.", "La posologie chez l'enfant et l'adolescent est la même", "La solution est injectée lentement", "Hypersensibilité au principe actif", "Capillary Leak Syndrome (CLS).", "Les patients ayant un œdème du larynx", "Afin d'assurer la traçabilité", "Aucune étude concernant les interactions", "Berinert IV est un composant physiologique", "On ignore si Berinert IV passe également"])
 d+=paras('La dose unitaire citée est de 20 unités internationales par kilogramme. La notice donne la même posologie pondérale chez l’enfant et l’adolescent ; elle mentionne la possibilité de répéter l’injection selon l’état clinique, sans intervalle fixe universel. Toute répétition et toute prophylaxie procédurale sont encadrées par le spécialiste. Aucun palier rénal ou hépatique chiffré n’est fourni dans cette notice.', 'Le syndrome de fuite capillaire est une contre-indication ; ce n’est pas une extension de l’indication de l’angio-œdème. Des thromboses ont été rapportées, notamment dans le contexte de doses très élevées utilisées pour cette indication non approuvée. Une hypersensibilité grave peut survenir avec un produit dérivé du plasma : arrêter l’administration et traiter la réaction si elle apparaît.', 'Reconstituer en conditions aseptiques avec le dispositif prévu. La solution ne doit pas être trouble ni contenir de particules. Elle ne doit pas être mélangée à un autre médicament. Les modalités précises de reconstitution et de conservation doivent être suivies dans la notice de la présentation disponible.', 'Noter le nom commercial et le numéro de lot à chaque administration. Le risque de transmission d’agents infectieux est réduit par les procédés de sélection et de fabrication, sans être totalement exclu. La notice recommande de considérer la vaccination contre les hépatites A et B chez les patients régulièrement exposés à ces préparations plasmatiques.', 'Pendant la grossesse, la notice réserve l’utilisation aux indications explicites ; pendant l’allaitement, elle demande une évaluation approfondie du bénéfice et du risque. Les recommandations internationales privilégient le C1-inhibiteur dérivé du plasma dans ces situations. Une atteinte laryngée exige une surveillance médicale et un accès immédiat aux gestes d’urgence, même après administration.', 'Le traitement à domicile nécessite une décision individuelle, une formation et des contrôles réguliers de la technique. La possession d’un flacon ne signifie pas que le patient est formé à l’injection intraveineuse ou qu’il peut gérer seul une atteinte des voies aériennes.')
 return l.subwindow('berinert','C1-inhibiteur : présentation intraveineuse et dose suisse',d,(21,18))
def adrenaline(l):
 d=paras('L’adrénaline stimule les récepteurs alpha et bêta : elle soutient la circulation, réduit l’œdème et traite le bronchospasme de l’anaphylaxie. La spécialité décrite est Adrenalin Sintetica 1 mg/ml en ampoule, autorisation 56551, notice de novembre 2024. La concentration, la voie et le contexte doivent être vérifiés avant administration.')
 d+=quote('56551',["La dose habituelle est de 500 microgrammes", "L’utilisation d’adrénaline pour un traitement systémique d’urgence", "Le meilleur site pour l’injection intramusculaire", "Surveiller le patient dès que possible", "L'adrénaline doit être utilisée avec prudence chez les patients atteints d'insuffisance rénale sévère"])
 lines=(D/'evidence/AIPS_56551.txt').read_text().splitlines();a=lines.index("Les doses chez l'enfant et l’adolescent sont:");b=lines.index('En injection intraveineuse ( i.v .)',a)
 d+='<p>Tableau pédiatrique de la notice, dans la section intramusculaire du choc anaphylactique :</p><blockquote><p>« '+escape(' '.join(lines[a:b]))+' »</p></blockquote>'
 d+=paras('La dose adulte citée est de 0,5 mg, soit 0,5 ml de la solution à 1 mg/ml, par voie intramusculaire dans la cuisse. La répétition se décide sur la persistance des signes respiratoires ou circulatoires. Ne pas confondre ces doses avec celles de l’arrêt cardiaque ni administrer la solution à 1 mg/ml en bolus intraveineux pour une anaphylaxie ordinaire.', 'La notice mentionne des demi-doses potentiellement plus sûres sous certains traitements associés. Cette mention n’est pas transformée ici en règle automatique : la recommandation britannique insiste sur l’administration précoce et adaptée de l’adrénaline intramusculaire. Les interactions, l’âge et le terrain nécessitent surveillance et avis expert, sans retarder un traitement vital.', 'La voie intraveineuse et les perfusions d’adrénaline relèvent d’équipes expérimentées avec surveillance continue. Une réaction réfractaire malgré deux doses intramusculaires appropriées appelle une aide experte précoce. Les antihistaminiques et corticoïdes ne remplacent pas l’adrénaline pour l’atteinte respiratoire ou circulatoire.', 'Les précautions concernent notamment maladie cardiaque, troubles du rythme, hyperthyroïdie, hypertension, insuffisance rénale sévère et médicaments sensibilisant le myocarde. La notice reconnaît l’usage justifié par une indication vitale malgré des contre-indications générales. Elle ne fournit pas de palier rénal ou hépatique chiffré pour ce traitement d’urgence.', 'Pendant la grossesse, la notice réserve l’utilisation aux situations clairement indispensables et décrit des précautions obstétricales. Une anaphylaxie menaçante exige une prise en charge maternelle urgente avec expertise obstétricale. L’allaitement est à interrompre selon la notice citée, sans différer le traitement vital. Surveiller tachycardie, arythmie, hypertension, douleur thoracique et réponse clinique.')
 d+=quote('56551',["Des études chez l'animal ont montré des effets tératogènes.", "L'adrénaline passe dans le lait maternel."])
 return l.subwindow('adrenaline','Adrénaline : forme, voie et doses suisses',d,(11,8))
def icatibant(l):
 d=paras('L’icatibant bloque le récepteur B2 de la bradykinine. Firazyr contient 30 mg dans une seringue de 3 ml pour injection sous-cutanée, autorisation suisse 58178, notice de février 2026. L’indication citée est l’angio-œdème héréditaire avec carence en C1-inhibiteur ; elle ne doit pas être étendue automatiquement à l’angio-œdème lié à un médicament.')
 d+=quote('58178',["Firazyr est indiqué dans le traitement symptomatique", "La dose recommandée chez les adultes", "Dans la majorité des cas, une seule injection", "Aucune posologie ne peut être recommandée", "Aucun ajustement de la dose n'est nécessaire chez les patients souffrant de troubles hépatiques", "Aucun ajustement de la dose n'est nécessaire chez les patients souffrant de troubles rénaux", "Hypersensibilité au principe actif", "Les patients souffrant d'œdèmes laryngés doivent toujours", "Firazyr ne doit être utilisé pendant la grossesse", "On ne sait pas si l'icatibant est excrété"])
 lines=(D/'evidence/AIPS_58178.txt').read_text().splitlines();a=lines.index('Tableau 1: Posologie chez les enfants et adolescents');b=lines.index("Dans l'étude clinique, il n'a pas été administré plus d'une injection de Firazyr par crise d'AOH.",a)
 d+='<p>Tableau suisse pour les enfants et adolescents de 2 à 17 ans :</p><blockquote><p>« '+escape(' '.join(lines[a:b+1]))+' »</p></blockquote>'
 d+=paras('Les doses et répétitions adultes ne sont pas des doses pédiatriques. Chez les 2–17 ans, la notice prévoit des paliers pondéraux et ne documente qu’une injection par crise ; la prescription et la préparation doivent suivre le protocole spécialisé. Un avis médical est nécessaire devant soulagement insuffisant ou récidive.', 'L’auto-administration suppose une décision spécialisée et une formation préalable. Une atteinte laryngée exige toujours une observation médicale même après une injection à domicile. La protection des voies aériennes ne doit pas attendre la réponse pharmacologique.', 'Prudence en cas de cardiopathie ischémique aiguë, angor instable ou accident vasculaire cérébral récent. Les réactions locales sont très fréquentes ; vertiges et fatigue peuvent gêner la conduite. Les inhibiteurs de l’enzyme de conversion sont contre-indiqués chez les patients atteints d’angio-œdème héréditaire.', 'La recommandation internationale sur l’angio-œdème héréditaire privilégie le C1-inhibiteur dérivé du plasma pendant grossesse et allaitement. Ce choix relève du spécialiste. La notice Firazyr impose une évaluation bénéfice-risque pendant grossesse et recommande une interruption de l’allaitement pendant douze heures après injection.')
 return l.subwindow('icatibant','Icatibant : indication précise et limites',d,(12,9))
